#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;

    Cat(string n) : name(n) {}

    void show() const {
        cout << name << " 蹲在这儿喵" << endl;
    }
};

int main() {
    const Cat c1("{name}");
    c1.show();
    return 0;
}
